import com.comsol.model.*;import com.comsol.model.util.*;import java.io.*;import java.util.*;
public class Original2VResumeSweep{static String root="D:/Github_codes/Flexible_Conductive_Film_CourseDesign_UESTC_24";public static void main(String[]a)throws Exception{String[] ps=a.length==0?new String[]{"0","25","50"}:a;File d=new File(root+"/Simulation_Results/Extended_Design");d.mkdirs();File csv=new File(d,"original_2V_pressure_sweep.csv"),log=new File(d,"original_2V_resume_solver_log.txt");TreeMap<Integer,String> rows=new TreeMap<Integer,String>();if(csv.exists()){BufferedReader r=new BufferedReader(new FileReader(csv));r.readLine();String s;while((s=r.readLine())!=null){String[]x=s.split(",");rows.put(Integer.parseInt(x[0]),s);}r.close();}PrintWriter l=new PrintWriter(new FileWriter(log,true));ModelUtil.connect("localhost",2036);try{Model m=ModelUtil.load("original2v_resume",root+"/COMSOL_Models/Pressure_Sensor_Original_2V.mph");if(!"2[V]".equals(m.component("comp1").physics("ecs").feature("term1").getString("V0")))throw new Exception("Terminal 1 not 2 V");boolean pa=m.study("std1").feature("param").isActive();m.study("std1").feature("param").active(false);for(String q:ps){int p=Integer.parseInt(q);if(rows.containsKey(p)){l.println("SKIP "+p);continue;}m.param().set("p1",p+"[kPa]");m.study("std1").run();String t="ev"+p;m.result().numerical().create(t,"EvalGlobal");m.result().numerical(t).set("expr",new String[]{"ecs.I0_1","ecs.V0_2-ecs.V0_3"});double[][]v=m.result().numerical(t).getReal();rows.put(p,p+","+(v[0][v[0].length-1]*1e3)+","+(v[1][v[1].length-1]*1e3));l.println("OK "+rows.get(p));PrintWriter w=new PrintWriter(new FileWriter(csv));w.println("Pressure_kPa,Current_mA,Vout_mV");for(String z:rows.values())w.println(z);w.close();}m.study("std1").feature("param").active(pa);m.save(root+"/COMSOL_Models/Pressure_Sensor_Original_2V.mph");}finally{l.close();ModelUtil.disconnect();}}}
